    // ... warp shuffle operations ...
}
__syncthreads();  // <-- THIS IS REMOVED

// First thread computes final loss for this batch
if (tid == 0) {
    // ... compute and atomicAdd ...
}
```

Looking at the code flow:
1. After the `for` loop reduction (lines 52-60), there's a `__syncthreads()` at line 60
2. Then the warp-level reduction happens (lines 63-87) only for `tid < 32`
3. The removed `__syncthreads()` was at line 91
4. Thread 0 reads from `shared_dot[0]`, `shared_pred_norm[0]`, `shared_target_norm[0]`

Wait, let me re-count the lines. Looking at the original code structure:

```cpp
// Store thread results in shared memory
shared_dot[tid] = dot_product;
shared_pred_norm[tid] = norm_pred;
shared_target_norm[tid] = norm_target;
__syncthreads();  // Line ~51

// Parallel reduction...
for (int stride = THREADS_PER_BLOCK / 2; stride >= 32; stride >>= 1) {
    if (tid < stride) {
        shared_dot[tid] += shared_dot[tid + stride];
        ...
    }
    __syncthreads();
}

// Warp-level reduction
if (tid < 32) {
    // warp shuffles...
    shared_dot[tid] += __shfl_down_sync(0xffffffff, shared_dot[tid], 16);
    ...
}
__syncthreads();  // Line 91 - THIS IS REMOVED

// First thread computes final loss
if (tid == 0) {
    ...
    float norm_product = sqrtf(shared_pred_norm[0] + epsilon) * sqrtf(shared_target_norm[0] + epsilon);
    float cosine_sim = shared_dot[0] / (norm_product + epsilon);
    ...
